import os, re, json, subprocess, base64
from flask import Flask, request, jsonify, Response
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

try:
    subprocess.run(['pip', 'install', '--upgrade', 'yt-dlp'], capture_output=True, timeout=60)
except Exception:
    pass

# HTML stored as base64 to avoid any encoding issues
HTML_B64 = ""
HTML = base64.b64decode(HTML_B64).decode('utf-8')

def valid(url):
    return bool(re.search(r'youtube|youtu\.be', url))

@app.route('/')
def index():
    return Response(HTML, mimetype='text/html')

@app.route('/api/info', methods=['POST'])
def info():
    data = request.get_json()
    url = data.get('url', '').strip()
    if not url or not valid(url):
        return jsonify({'error': 'Invalid URL'}), 400
    try:
        r = subprocess.run(['yt-dlp', '--dump-json', '--no-playlist', url], capture_output=True, text=True, timeout=30)
        if r.returncode != 0:
            return jsonify({'error': 'Could not fetch video info'}), 400
        i = json.loads(r.stdout)
        fs = []
        seen = set()
        for f in i.get('formats', []):
            h = f.get('height')
            v = f.get('vcodec', 'none')
            if h and v != 'none' and h not in seen and f.get('ext') in ('mp4', 'webm'):
                seen.add(h)
                fs.append({'height': h, 'label': f'{h}p'})
        fs = sorted(fs, key=lambda x: x['height'], reverse=True)
        fi = [next((f for f in fs if f['height'] == s), None) for s in [2160, 1080, 720, 480]]
        fi = [f for f in fi if f]
        d = i.get('duration', 0)
        ds = f"{int(d//60)}:{int(d%60):02d}" if d else 'N/A'
        return jsonify({'title': i.get('title', '?'), 'channel': i.get('uploader', '?'), 'duration': ds, 'thumbnail': i.get('thumbnail', ''), 'video_id': i.get('id', ''), 'formats': fi})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/download', methods=['POST'])
def download():
    data = request.get_json()
    url = data.get('url', '').strip()
    q = str(data.get('quality', '1080')).replace('p', '')
    fmt = data.get('format', 'mp4')
    if not url or not valid(url):
        return jsonify({'error': 'Invalid URL'}), 400
    try:
        sel = 'bestaudio[ext=m4a]/bestaudio' if fmt == 'mp3' else f'best[height<=={q}][ext=mp4]/best[height<=={q}]/best'
        r = subprocess.run(['yt-dlp', '-f', sel, '--get-url', '--no-playlist', url], capture_output=True, text=True, timeout=25)
        if r.returncode != 0 or not r.stdout.strip():
            r = subprocess.run(['yt-dlp', '-f', 'best', '--get-url', '--no-playlist', url], capture_output=True, text=True, timeout=25)
        if r.returncode != 0 or not r.stdout.strip():
            return jsonify({'error': 'Could not get download URL'}), 500
        return jsonify({'download_url': r.stdout.strip().split("\n")[0], 'filename': f'video.{fmt}'})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))
